def minPath(grid, k):
    n = len(grid)

    # Locate the cell containing the smallest value, 1
    cur_r = cur_c = -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                cur_r, cur_c = r, c
                break
        if cur_r != -1:
            break

    path = [1]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for _ in range(k - 1):
        best_val = float('inf')
        best_r = best_c = -1

        for dr, dc in directions:
            nr, nc = cur_r + dr, cur_c + dc
            if 0 <= nr < n and 0 <= nc < n:
                val = grid[nr][nc]
                if val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc

        path.append(best_val)
        cur_r, cur_c = best_r, best_c

    return path
```

